+// API keys and roles. Keys live in the store as apiKeys: [{ key, name, role }].
+import { AppError } from "../errors.js";
+
+/** Roles, least to most privileged. */
+export const ROLES = Object.freeze(["viewer", "cook", "manager"]);
+
+// What a cook may do besides reading: [method, path pattern].
+const COOK_WRITES = [
+  ["POST", /^\/recipes\/[^/]+\/cook$/],
+  ["POST", /^\/batches\/[^/]+\/waste$/],
+  ["POST", /^\/temperatures$/],
+  ["POST", /^\/stocktakes\/[^/]+\/counts$/],
+];
+
+/** The API key record for an Authorization header value, or throws unauthorized. */
+export function authenticate(store, authorization) {
+  const m = /^Bearer\s+(\S+)$/i.exec(String(authorization ?? "").trim());
+  const found = m && (store.data.apiKeys ?? []).find((k) => k.key === m[1]);
+  if (!found) throw new AppError("unauthorized");
+  return found;
+}
+
+/** Throws forbidden unless the key's role may make this request. */
+export function authorize(role, method, path) {
+  const ok =
+    role === "manager" ||
+    (role === "viewer" && method === "GET" && path !== "/audit") ||
+    (role === "cook" && (method === "GET" ? path !== "/audit" : COOK_WRITES.some(([mt, re]) => mt === method && re.test(path))));
+  if (!ok) throw new AppError("forbidden", { role, method, path });
+}
+
+/** Appends an audit entry (time, key name, method, path, status). */
+export function recordAudit(store, { at, name, method, path, status }) {
+  store.data.audit.push({ at, name, method, path, status });
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...store.data.audit].reverse();
+}
